<template>
 <div class="ai-logs">
  <form class="panel filters" @submit.prevent="search">
   <label>开始日期<input v-model="filters.from" type="date" required aria-label="开始日期" /></label>
   <label>结束日期<input v-model="filters.to" type="date" required aria-label="结束日期" /></label>
   <label>来源端<el-select v-model="filters.client" placeholder="全部来源" aria-label="来源端"><el-option label="全部来源" value=""/><el-option v-for="(label,key) in clientLabels" :key="key" :label="label" :value="key"/></el-select></label>
   <label>功能<el-select v-model="filters.feature" placeholder="全部功能" aria-label="调用功能"><el-option label="全部功能" value=""/><el-option v-for="(label,key) in featureLabels" :key="key" :label="label" :value="key"/></el-select></label>
   <label>结果<el-select v-model="filters.outcome" placeholder="全部结果" aria-label="调用结果"><el-option label="全部结果" value=""/><el-option v-for="(label,key) in outcomeLabels" :key="key" :label="label" :value="key"/></el-select></label>
   <div class="filter-actions"><el-button native-type="submit" type="primary" :disabled="loading">查询</el-button><el-button :loading="loading" @click="load">刷新</el-button></div>
  </form>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
  <section class="metrics" aria-label="当前筛选范围统计"><article><span>操作请求</span><strong>{{summary.requests}}</strong></article><article><span>实际模型调用</span><strong>{{summary.modelCalls}}</strong></article><article><span>成功操作</span><strong>{{summary.success}}</strong></article><article><span>失败操作</span><strong>{{summary.failed}}</strong></article><article><span>拒绝或受限</span><strong>{{summary.blocked}}</strong></article><article><span>已知 Token 用量</span><strong>{{summary.totalTokens.toLocaleString()}}</strong><small v-if="summary.unknownTokenCalls">{{summary.unknownTokenCalls}} 次模型调用未返回用量</small></article></section>
  <section class="panel records" :aria-busy="loading"><header><h3>调用明细 <small>共 {{total}} 条</small></h3><span>北京时间</span></header>
   <p class="empty" v-if="!items.length">{{loading?'正在读取记录…':'当前条件下没有调用记录。'}}</p>
   <div v-else class="table-wrap"><table><thead><tr><th>时间与账号</th><th>来源 / 功能</th><th>模型 / 调用数</th><th>结果</th><th>耗时</th><th>Token 用量</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td data-label="时间与账号"><time>{{time(row.startedAt)}}</time><strong>{{row.displayName||row.username||'账号 '+row.accountId}}</strong><small>{{row.username}}</small></td><td data-label="来源 / 功能"><strong>{{clientLabels[row.client]||'—'}}</strong><span>{{featureLabels[row.feature]||row.feature}}</span></td><td data-label="模型 / 调用数"><strong>{{row.model||'未调用模型'}}</strong><small>{{row.provider||'—'}} · {{row.modelCalls}} 次</small></td><td data-label="结果"><span class="result" :class="row.outcome">{{outcomeLabels[row.outcome]||row.outcome}}</span><small v-if="row.failureType">{{row.failureType==='timeout'?'连接超时':'网络失败'}}</small><small v-if="row.upstreamStatus>=400">模型 HTTP {{row.upstreamStatus}}</small><small v-if="row.httpStatus>=400">接口 HTTP {{row.httpStatus}}</small></td><td data-label="耗时">{{row.durationMs==null?'—':(row.durationMs/1000).toFixed(1)+' 秒'}}</td><td data-label="Token 用量"><strong>{{row.totalTokens==null?'—':row.totalTokens.toLocaleString()}}</strong><small>输入 {{row.promptTokens??'—'}} · 输出 {{row.completionTokens??'—'}}</small><small v-if="row.cachedTokens!=null">缓存命中 {{row.cachedTokens}}</small></td></tr></tbody></table></div>
   <footer><span>每页 20 条</span><div><el-button :disabled="loading||page<=1" @click="changePage(-1)">上一页</el-button><span>{{page}} / {{Math.max(1,Math.ceil(total/20))}}</span><el-button :disabled="loading||page*20>=total" @click="changePage(1)">下一页</el-button></div></footer>
  </section>
  <p class="help">每次可查 31 天；注释按实际模型批次记录，Token 未返回时显示“—”。</p>
 </div>
</template>
<script setup>
import {ref,onMounted} from 'vue'
import {getAiCallLogs} from '../api'
const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10)
const filters=ref({from:today,to:today,client:'',feature:'',outcome:''}),loading=ref(false),error=ref(''),page=ref(1),total=ref(0),items=ref([])
const summary=ref({requests:0,modelCalls:0,success:0,failed:0,blocked:0,totalTokens:0,unknownTokenCalls:0})
const clientLabels={web:'网页',miniprogram:'小程序',android:'App'}
const featureLabels={knowledge_chat:'知识问答',raw_summary:'原粮周总结',robot_annotation_start:'机器人注释任务',robot_annotations:'机器人注释批次',robot_question:'机器人提问',robot_modify:'机器人修改建议',robot_connection:'模型连接检查'}
const outcomeLabels={success:'成功',failed:'失败',blocked:'请求被拒绝',fallback:'降级为站内检索',restricted:'话题受限',pending:'处理中 / 结果待确认',interrupted:'连接中断'}
const time=value=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})
let sequence=0,applied={...filters.value}
async function load(){const id=++sequence;loading.value=true;error.value='';try{const result=(await getAiCallLogs({...applied,page:page.value,pageSize:20})).data;if(id!==sequence)return;items.value=result.items;total.value=result.total;summary.value=result.summary}catch(e){if(id===sequence)error.value=e.response?.data?.msg||e.message}finally{if(id===sequence)loading.value=false}}
function search(){applied={...filters.value};page.value=1;return load()}
function changePage(delta){if(loading.value)return;page.value=Math.max(1,page.value+delta);return load()}
onMounted(load)
</script>
<style scoped>
.ai-logs{max-width:1600px;margin:auto;display:grid;gap:18px;color:#233c50;min-width:0}.records>header,.records>footer{display:flex;justify-content:space-between;align-items:center;gap:16px}.ai-logs h3{margin:0;font-size:16px}.ai-logs p{font-size:13px;line-height:1.8;color:#6b7b8d}.panel{padding:22px;background:white;border:1px solid #e2e8ef;border-radius:12px;min-width:0}.filters{display:grid;grid-template-columns:repeat(2,minmax(130px,1fr)) repeat(3,minmax(110px,1fr)) auto;align-items:end;gap:12px;padding:18px}.filters label{display:grid;gap:8px;font-size:12px;color:#536679;min-width:0}.filters input[type=date]{border:1px solid #dce3eb;border-radius:6px;height:40px;padding:0 10px;font:inherit;font-size:14px;color:#324b60;background:white;min-width:0;width:100%;box-sizing:border-box}.filters .el-select{width:100%}.filters :deep(.el-select__wrapper){height:40px;min-height:40px;box-sizing:border-box}.filter-actions{display:flex;gap:8px}.filter-actions .el-button{height:40px;margin:0;padding:0 14px}.metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}.metrics article{background:#f6faf9;border:1px solid #dceae6;border-radius:10px;padding:17px;display:grid;gap:9px}.metrics span{font-size:12px;color:#627889}.metrics strong{font-size:27px;color:#0d726f}.metrics small{font-size:11px;color:#79899a}.records>header{margin-bottom:20px}.records small,.records>header>span,.records>footer{font-size:12px;color:#7a8b9c}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}th{font-size:12px;color:#708193;font-weight:500;padding:12px 10px;background:#f7f9fc}td{padding:17px 10px;border-bottom:1px solid #edf1f5;vertical-align:top;line-height:1.7;overflow-wrap:anywhere}td strong,td span,td small,td time{display:block}td strong{font-weight:600}td small{margin-top:3px}.result{display:inline-block;width:fit-content;padding:2px 8px;border-radius:5px;background:#f0f3f7;color:#62768c;font-size:12px}.result.success{background:#eaf6f0;color:#26755a}.result.failed,.result.interrupted{background:#fff0ef;color:#a5413c}.result.blocked,.result.fallback,.result.restricted{background:#fff6e7;color:#986e31}.records>footer{margin-top:20px}.records>footer>div{display:flex;align-items:center;gap:12px}.empty{text-align:center;padding:45px 10px}.help{margin:0}
@media(max-width:1050px){.filters{grid-template-columns:repeat(3,minmax(0,1fr))}.metrics{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:760px){.panel{padding:15px}.filters{gap:12px;grid-template-columns:repeat(2,minmax(0,1fr))}.filter-actions{align-self:end}.filter-actions .el-button{flex:1;padding:0 8px}.filters input[type=date],.filters :deep(.el-select__wrapper),.filter-actions .el-button{height:44px;min-height:44px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.metrics article{padding:14px}.metrics strong{font-size:24px}table,tbody,tr,td{display:block}thead{display:none}tr{border:1px solid #e5ebf0;border-radius:8px;padding:10px;margin-bottom:12px}td{position:relative;display:grid;grid-template-columns:90px minmax(0,1fr);padding:9px 0;border:0;min-width:0}td:before{content:attr(data-label);grid-column:1;grid-row:1/5;font-size:12px;color:#7a8b9c}td>*{grid-column:2}.records>header{align-items:flex-start;flex-direction:column;gap:9px}.records>footer{flex-direction:column}.records .el-button{min-height:44px}}
</style>
